import mitt from 'mitt'

export enum UpgradePlanEvents {
	OPEN_MODAL = 'OPEN_MODAL'
}

export enum PurchaseCreditsEvents {
	OPEN_MODAL = 'OPEN_MODAL'
}

export enum ChatEvents {
	STREAMING_DONE = 'STREAMING_DONE'
}

export enum ErrorFixEvents {
	ERROR_FIX_SUBMITTED = 'ERROR_FIX_SUBMITTED'
}

export enum CloseChatEvents {
	CLOSE_CHAT = 'CLOSE_CHAT'
}

export enum PathChangeEvents {
	PATH_CHANGE = 'PATH_CHANGE'
}

export enum ModeChangeEvents {
	MODE_CHANGE = 'MODE_CHANGE'
}

export const chatEmitter = mitt<{
	[ChatEvents.STREAMING_DONE]: void
}>()

export const upgradePlanEmitter = mitt<{
	[UpgradePlanEvents.OPEN_MODAL]: void
}>()

export const purchaseCreditsEmitter = mitt<{
	[PurchaseCreditsEvents.OPEN_MODAL]: void
}>()

export const errorFixEmitter = mitt<{
	[ErrorFixEvents.ERROR_FIX_SUBMITTED]: { error: string }
}>()

export const closeChatEmitter = mitt<{
	[CloseChatEvents.CLOSE_CHAT]: void
}>()

export const pathChangeEmitter = mitt<{
	[PathChangeEvents.PATH_CHANGE]: { path: string }
}>()

export const modeChangeEmitter = mitt<{
	[ModeChangeEvents.MODE_CHANGE]: { mode: 'web' | 'mobile' }
}>()
